```

`defer` is Go's resource cleanup mechanism — guaranteed to run when the function returns (normally or via panic). Use for: closing files, releasing locks, HTTP response bodies.

```go
// Basic function
func add(a, b int) int { return a + b }

// Multiple return values (idiomatic for error handling)
func divide(a, b float64) (float64, error) {
    if b == 0 {
        return 0, fmt.Errorf("division by zero")
    }
    return a / b, nil
}
result, err := divide(10, 3)

// Named return values
func minmax(nums []int) (min, max int) {
    min, max = nums[0], nums[0]
    for _, n := range nums[1:] {
        if n < min { min = n }
        if n > max { max = n }
    }
    return  // naked return
}

// Variadic
func sum(nums ...int) int {
    total := 0
    for _, n := range nums { total += n }
    return total
}
sum(1, 2, 3)
sum(nums...)   // spread slice

// Closure
func makeCounter() func() int {
    count := 0
    return func() int {
        count++
        return count
    }
}
c := makeCounter()
c(); c(); c()  // 1, 2, 3
```

