    X, Y float64
}

type Person struct {
    Name  string
    Age   int
    Email string `json:"email,omitempty"`  // struct tag
}

// Value receiver method
func (p Point) Distance(other Point) float64 {
    dx, dy := p.X-other.X, p.Y-other.Y
    return math.Sqrt(dx*dx + dy*dy)
}

// Pointer receiver method (can modify the struct)
func (p *Point) Scale(factor float64) {
    p.X *= factor
    p.Y *= factor
}

// Embedding (composition, not inheritance)
type Animal struct{ Name string }
func (a Animal) Speak() string { return a.Name + " speaks" }

type Dog struct {
    Animal         // embedded — methods and fields promoted
    Breed string
}

dog := Dog{Animal: Animal{"Rex"}, Breed: "Lab"}
dog.Speak()   // promoted from Animal — no Animal. prefix needed
dog.Name      // also promoted
