```go
// Interface definition
type Shape interface {
    Area() float64
    Perimeter() float64
}

// Circle implements Shape — IMPLICITLY (no 'implements' keyword)
type Circle struct{ Radius float64 }
func (c Circle) Area() float64      { return math.Pi * c.Radius * c.Radius }
func (c Circle) Perimeter() float64 { return 2 * math.Pi * c.Radius }

// Use the interface
var s Shape = Circle{5.0}
fmt.Println(s.Area())

// Interface composition
type ReadWriter interface {
    io.Reader
    io.Writer
}

// Empty interface / any
var anything any = 42
anything = "now a string"

// Type assertion
str, ok := anything.(string)
```

Implementation is **implicit** — if a type has all the methods an interface requires, it satisfies the interface. No `implements` declaration needed. This enables decoupled design.

```go
// Goroutine — launch with 'go'
go func() {
    fmt.Println("running concurrently")
}()

// Channel — typed communication pipe
ch  := make(chan int)         // unbuffered (blocks until received)
bch := make(chan int, 100)    // buffered (blocks when full)

// Send and receive
go func() { ch <- 42 }()  // send in goroutine
val := <-ch               // receive (blocks)

// Close channel
close(ch)
val, ok := <-ch   // ok=false when closed and empty

// Range over channel
for v := range ch {
    fmt.Println(v)
}

// select — multiplex channels
select {
case msg := <-ch1:
    fmt.Println("ch1:", msg)
case msg := <-ch2:
    fmt.Println("ch2:", msg)
case <-time.After(time.Second):
    fmt.Println("timeout")
default:
    fmt.Println("no data ready")  // non-blocking
}
```

