// Mutex — protect shared state
var mu sync.Mutex
var counter int

func increment() {
    mu.Lock()
    defer mu.Unlock()  // always use defer to ensure unlock
    counter++
}

// sync.Once — run exactly once (singleton initialization)
var once sync.Once
var instance *MyService

func getInstance() *MyService {
    once.Do(func() {
        instance = &MyService{}
    })
    return instance
}
