import "errors"

// errors.New
err := errors.New("something went wrong")

// fmt.Errorf with %w — wraps an error
wrapped := fmt.Errorf("outer: %w", err)

// errors.Is — check through the chain
errors.Is(wrapped, err)   // true

// Custom error type
type ValidationError struct {
    Field   string
    Message string
}
func (e *ValidationError) Error() string {
    return fmt.Sprintf("validation error: %s - %s", e.Field, e.Message)
}

// errors.As — extract typed error
var ve *ValidationError
if errors.As(err, &ve) {
    fmt.Println("Field:", ve.Field)
}

// Idiomatic pattern: always check errors
result, err := someOperation()
if err != nil {
    return fmt.Errorf("myFunc: %w", err)  // wrap with context
}
